# @@ partition around the last element
def partition(a: Arr, lo, hi) {
    pivot = a[hi]
    i = lo
    for j from lo to hi {
        if a[j] < pivot {
            a[i], a[j] = a[j], a[i]
            i = py_int(i + 1)
        }
    }
    a[i], a[hi] = a[hi], a[i]
    return i
}
# @@ sort the two sides
def quicksort(a: Arr, lo, hi) {
    if lo < hi {
        p = partition(a, lo, hi)
        quicksort(a, lo, py_int(p - 1))
        quicksort(a, py_int(p + 1), hi)
    }
}
# @@ sort a list in place
data = [3.5, -1.0, 7.25, 0.0, 2.0, 7.25, -8.5, 4.0]
quicksort(data, 0, len(data) - 1)
print(fmt(data))
# @@ checks
py_all1 = true
for py_k2 to len(data) - 1 {
    if not (data[py_k2] <= data[py_int(py_k2 + 1)]) {
        py_all1 = false
        break
    }
}
if not py_all1 {
    stop("AssertionError")
}
